CREATE TABLE managed_model_keys(
 id uuid PRIMARY KEY,owner_user_id uuid NOT NULL REFERENCES admins(id),created_by_user_id uuid NOT NULL REFERENCES admins(id),
 name text NOT NULL,scope text NOT NULL CHECK(scope IN('private','site')),base_url text NOT NULL,client_type text NOT NULL,
 secret_ciphertext text NOT NULL,key_digest text NOT NULL,key_hint text NOT NULL,enabled boolean NOT NULL DEFAULT true,archived boolean NOT NULL DEFAULT false,revision integer NOT NULL DEFAULT 1,
 models jsonb NOT NULL DEFAULT '[]',catalog_synced_at timestamptz,catalog_error text,currency text NOT NULL DEFAULT 'CNY',prices jsonb NOT NULL DEFAULT '{}',limits jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_user_id,base_url,key_digest,client_type)
);
CREATE TABLE managed_model_requests(id uuid PRIMARY KEY,key_id uuid NOT NULL REFERENCES managed_model_keys(id),user_id uuid NOT NULL REFERENCES admins(id),bot_id uuid NOT NULL REFERENCES managed_bots(id),reason text NOT NULL,requested jsonb NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected','cancelled')),review_note text NOT NULL DEFAULT '',reviewed_by uuid REFERENCES admins(id),created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz);
CREATE UNIQUE INDEX ON managed_model_requests(key_id,user_id) WHERE status='pending';
CREATE TABLE managed_model_grants(id uuid PRIMARY KEY,key_id uuid NOT NULL REFERENCES managed_model_keys(id),user_id uuid NOT NULL REFERENCES admins(id),enabled boolean NOT NULL DEFAULT true,bot_ids uuid[] NOT NULL DEFAULT '{}',group_ids uuid[] NOT NULL DEFAULT '{}',model_ids text[] NOT NULL DEFAULT '{}',features text[] NOT NULL DEFAULT '{}',expires_at timestamptz NOT NULL,limits jsonb NOT NULL,revision integer NOT NULL DEFAULT 1,created_by_user_id uuid NOT NULL REFERENCES admins(id),UNIQUE(key_id,user_id));
CREATE TABLE managed_model_usage(id uuid PRIMARY KEY,key_id uuid NOT NULL REFERENCES managed_model_keys(id),user_id uuid NOT NULL REFERENCES admins(id),actor_user_id uuid REFERENCES admins(id),bot_id uuid NOT NULL REFERENCES managed_bots(id),group_id uuid,feature text NOT NULL,model_id text NOT NULL,currency text NOT NULL,grant_id uuid REFERENCES managed_model_grants(id),reserved_tokens bigint NOT NULL,reserved_cost numeric(24,6),input_tokens bigint,output_tokens bigint,cached_tokens bigint,cost numeric(24,6),status text NOT NULL CHECK(status IN('reserved','completed','unknown','failed')),dispatched boolean NOT NULL DEFAULT false,error_code text,created_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz);
CREATE INDEX ON managed_model_usage(key_id,user_id,created_at);
CREATE INDEX ON managed_model_usage(bot_id,created_at);
